  { id: "U1_S05", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜನಪದ, ಗೀತೆ, ಕಥೆ, ಲಾವಣಿ ಒಳಗೊಂಡಿರುವ ಸಾಹಿತ್ಯ ಯಾವುದು?", a: "ಮೌಖಿಕ ಸಾಹಿತ್ಯ" },
  { id: "U1_S06", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಉತ್ಖನನ ಎಂದರೇನು?", a: "ಮಾನವನ ಪ್ರಾಚೀನ ಅವಶೇಷ ಅಥವಾ ಪಳೆಯುಳಿಕೆಗಳನ್ನು ಹೊರತೆಗೆಯಲು ನಡೆಸುವ ವೈಜ್ಞಾನಿಕ ಭೂ ಅಗೆತ." },
  { id: "U1_S07", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಮಾನವರ ವಿಕಾಸ ಎಷ್ಟು ವರ್ಷಗಳ ಹಿಂದೆಯಾಯಿತು?", a: "ಸುಮಾರು 18 ಲಕ್ಷ ವರ್ಷಗಳ ಹಿಂದೆ." },
  { id: "U1_S08", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಅಕ್ಷರದ ಪರಿಚಯವೇ ಇಲ್ಲದ ಇತಿಹಾಸದ ಕಾಲಘಟ್ಟ ಯಾವುದು?", a: "ಪ್ರಾಗೈತಿಹಾಸಿಕ ಕಾಲ" },
  { id: "U1_S09", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಲೋಹಗಳ ಬಳಕೆ ಪ್ರಾರಂಭವಾದ ಕಾಲ ಯಾವುದು?", a: "ನವ ಶಿಲಾಯುಗದ ಕೊನೆಯ ಕಾಲ" },
  { id: "U1_K01", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಇತಿಹಾಸದ ಮೂರು ಪ್ರಧಾನ ಕಾಲಗಳು ಯಾವುವು?", a: "1) ಪ್ರಾಗೈತಿಹಾಸಿಕ ಕಾಲ 2) ಪೂರ್ವಭಾವಿ ಕಾಲ 3) ಇತಿಹಾಸ ಕಾಲ." },
  { id: "U1_K02", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಹಳೆಯ ಶಿಲಾಯುಗದ ಮಾನವರ ಉಪಕರಣಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಹಿರೇಚಕ್ಕೆ, ಚಾಕು, ಕಲ್ಲುಳಿ, ಮೋನೆ ಮುಂತಾದ ಒರಟಾದ ದೊಡ್ಡ ದೊಡ್ಡ ಶಿಲಾ ಉಪಕರಣಗಳು." },
  { id: "U1_K03", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಇತಿಹಾಸದ ಪ್ರಮುಖ ಆಧಾರಗಳು ಯಾವುವು?", a: "1) ಸಾಹಿತ್ಯ ಆಧಾರಗಳು (ಲಿಖಿತ ಮತ್ತು ಮೌಖಿಕ) 2) ಪುರಾತತ್ವ ಆಧಾರಗಳು (ಶಾಸನಗಳು, ನಾಣ್ಯಗಳು, ಸ್ಮಾರಕಗಳು)." },
  { id: "U1_K04", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಪ್ರಾಗೈತಿಹಾಸಿಕ ಕಾಲದ ಮೂರು ಹಂತಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಹಳೆಯ ಶಿಲಾಯುಗ, ಮಧ್ಯ ಶಿಲಾಯುಗ ಮತ್ತು ನವ ಶಿಲಾಯುಗ." },
  { id: "U1_K05", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ಕಿ.ಉ", marks: 2, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿಶ್ಲೇಷಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಕಬ್ಬಿಣದ ಪರಿಚಯದಿಂದ ಉಂಟಾದ ಬದಲಾವಣೆಗಳಾವುವು?", a: "ಕೃಷಿ ಮತ್ತು ಕರಕುಶಲ ಉಪಕರಣಗಳು ಚುರುಕುಗೊಂಡವು; ಗಂಗಾ ನದಿ ಬಯಲಿನಲ್ಲಿ ಕೃಷಿ ಉತ್ಪಾದನೆ ಹೆಚ್ಚಿ ಗಣರಾಜ್ಯಗಳು ಹಾಗೂ ಮೌರ್ಯ ಸಾಮ್ರಾಜ್ಯದ ಉದಯಕ್ಕೆ ಕಾರಣವಾಯಿತು." },
  { id: "U1_L01", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವಿ.ಉ", marks: 4, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ಸಮರ್ಥಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಮಕ್ಕಳೇ, ನಮಗೆ ಇತಿಹಾಸ ಏಕೆ ಬೇಕು? ನಿಮ್ಮ ಮಾತುಗಳಲ್ಲಿ ವಿವರಿಸಿ.", a: "ಇತಿಹಾಸವು ನಮ್ಮ ದೇಶದ ಸ್ಮರಣ ಶಕ್ತಿಯಾಗಿದೆ; ಪೂರ್ವಿಕರ ತಪ್ಪು-ಒಪ್ಪುಗಳನ್ನು ತಿಳಿಸಿ ಮುಂದಿನ ತೀರ್ಮಾನಗಳಿಗೆ ಎಚ್ಚರಿಸುತ್ತದೆ; ನಮ್ಮ ಭವ್ಯ ಸಂಸ್ಕೃತಿ ಮತ್ತು ಪರಂಪರೆಯನ್ನು ಪರಿಚಯಿಸಿ ಪ್ರೇರಣೆ ನೀಡುತ್ತದೆ." },
  { id: "U1_L02", unit: "ಇತಿಹಾಸ ಪರಿಚಯ ಮತ್ತು ಆರಂಭಿಕ ಸಮಾಜ", type: "ವಿ.ಉ", marks: 4, obj: "ಜ್ಞಾನ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಜೀವಿಗಳ ವಿಕಾಸದ ಹಂತಗಳು ಮತ್ತು ಮಾನವನ ವಿಕಾಸವನ್ನು ಕುರಿತು ಬರೆಯಿರಿ.", a: "ಮೊದಲು ಏಕಕೋಶ ಜೀವಿಗಳು, ನಂತರ ಮೀನು, ಸಸ್ಯ, ಕೀಟ, ಉಭಯವಾಸಿ, ಸರಿಸೃಪ, ಪಕ್ಷಿ ಮತ್ತು ಸಸ್ತನಿಗಳು ವಿಕಾಸವಾದವು. ಸುಮಾರು 18 ಲಕ್ಷ ವರ್ಷಗಳ ಹಿಂದೆ ದಕ್ಷಿಣ ಆಫ್ರಿಕಾದಲ್ಲಿ ಆಧುನಿಕ ದೈಹಿಕ ರಚನೆಯ ಮಾನವರು ಉಗಮವಾಗಿ ಜಗತ್ತಿನೆಲ್ಲೆಡೆ ವಲಸೆ ಹೋದರು." },

  // ==========================================
  // ಅಧ್ಯಾಯ 2: ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ
  // ==========================================
  { id: "U2_F01", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜಗತ್ತಿನಲ್ಲಿ ಅಹಿಂಸೆಯ ಶ್ರೇಷ್ಠತಮ ಪ್ರತಿಪಾದಕರು ____________.", a: "ಭಾರತೀಯರು" },
  { id: "U2_F02", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜಗತ್ತಿನ ಅತಿ ಎತ್ತರದ ಬುದ್ಧನ ಮೂರ್ತಿ ಅಫ್ಘಾನಿಸ್ತಾನದ ____________ ನಲ್ಲಿದೆ.", a: "ಬಾಮಿಯಾನ್" },
  { id: "U2_F03", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಾಚೀನ ಕಾಲದಲ್ಲಿ ಗುಜರಾತಿನ ಸೂರತ್ ____________ ನಿರ್ಮಾಣಕ್ಕೆ ಪ್ರಸಿದ್ಧವಾಗಿತ್ತು.", a: "ನೌಕಾ (ಹಡಗು)" },
  { id: "U2_F04", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತ ಸರ್ಕಾರ ಶ್ರೇಷ್ಠ ವಿಜ್ಞಾನಿಗಳಿಗೆ ನೀಡುವ ಪ್ರಶಸ್ತಿ ____________.", a: "ಆರ್ಯಭಟ ಪ್ರಶಸ್ತಿ" },
  { id: "U2_F05", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪೈಥಾಗೊರಸ್ ಪ್ರಮೇಯವನ್ನು ಆತನಿಗಿಂತ ಮೊದಲೇ ಗುರುತಿಸಿದ್ದ ಭಾರತೀಯ ಗಣಿತಜ್ಞ ____________.", a: "ಬೋಧಾಯನ" },
  { id: "U2_F06", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತದ ಮೊಟ್ಟ ಮೊದಲ ಕೃತಕ ಉಪಗ್ರಹ ____________.", a: "ಆರ್ಯಭಟ" },
  { id: "U2_F07", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕಾಂಬೋಡಿಯಾದ ____________ ಎಂಬಲ್ಲಿ ಭವ್ಯ ಹಿಂದೂ ದೇವಾಲಯವಿದೆ.", a: "ಅಂಕೋರ್ ವಾಟ್" },
  { id: "U2_F08", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಏಷ್ಯಾಟಿಕ್ ಸೊಸೈಟಿಯನ್ನು ಸ್ಥಾಪಿಸಿದ ವಿದ್ವಾಂಸರು ____________.", a: "ಸರ್ ವಿಲಿಯಂ ಜೋನ್ಸ್" },
  { id: "U2_S01", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತ ಎಂಬ ಹೆಸರು ಬರಲು ಐತಿಹಾಸಿಕ ಹಿನ್ನೆಲೆ ಏನು?", a: "ಭರತ ಚಕ್ರವರ್ತಿ ಆಳಿದ ನಾಡು ಭರತಖಂಡ ಅಥವಾ ಭಾರತ ಎನಿಸಿತು." },
  { id: "U2_S02", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪರ್ಷಿಯನ್ನರು ಭಾರತವನ್ನು ಏನೆಂದು ಕರೆದಿದ್ದಾರೆ?", a: "ಹಿಂದೂಸ್ಥಾನ" },
  { id: "U2_S03", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂಸ್ಕೃತ ಭಾಷೆಯ ನುಡಿಗಟ್ಟು ಅದ್ಭುತ ಎಂದು ಪ್ರಶಂಸಿಸಿದ ಪಾಶ್ಚಾತ್ಯ ವಿದ್ವಾಂಸ ಯಾರು?", a: "ವಿಲಿಯಂ ಜೋನ್ಸ್" },
  { id: "U2_S04", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕಳಿಂಗದ ಪ್ರಸ್ತುತ ಹೆಸರೇನು?", a: "ಒಡಿಶಾ" },
  { id: "U2_S05", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸೊನ್ನೆಯನ್ನು ಸಂಖ್ಯಾ ಸೂಚಕವಾಗಿ ಬಳಸಿದ ಮೊದಲ ದೇಶ ಯಾವುದು?", a: "ಭಾರತ" },
  { id: "U2_S06", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸೂರ್ಯನ ಸುತ್ತ ಭೂಮಿ ಪರಿಭ್ರಮಿಸುತ್ತದೆ ಎಂದು ಹೇಳಿದ ಭಾರತೀಯ ವಿಜ್ಞಾನಿ ಯಾರು?", a: "ಆರ್ಯಭಟ" },
  { id: "U2_S07", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ವಸ್ತುವಿನ ಅವಿಭಾಜ್ಯ ಕಣವಾದ ಅಣುವಿನ ಪರಿಕಲ್ಪನೆ ನೀಡಿದ ಭಾರತೀಯ ತತ್ವಜ್ಞಾನಿ ಯಾರು?", a: "ಕಣಾದ ಮಹರ್ಷಿ" },
  { id: "U2_S08", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂಸ್ಕೃತದಿಂದ ಇಂಗ್ಲಿಷ್‌ಗೆ ತರ್ಜಮೆಗೊಂಡ ಭಾರತದ ಮೊದಲ ಕೃತಿ ಯಾವುದು?", a: "ಭಗವದ್ಗೀತೆ" },
  { id: "U2_K01", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಬೌದ್ಧ ಧರ್ಮವು ಪಸರಿಸಿದ ನಾಲ್ಕು ಪ್ರಮುಖ ದೇಶಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಆಫ್ಘಾನಿಸ್ತಾನ್, ಟಿಬೆಟ್, ಚೀನಾ, ಕೊರಿಯಾ, ಜಪಾನ್ ಮತ್ತು ಶ್ರೀಲಂಕಾ." },
  { id: "U2_K02", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಭಾರತದಲ್ಲಿರುವ ನಾಲ್ಕು ಪ್ರಮುಖ ವಿಶ್ವ ಪರಂಪರೆಯ ತಾಣಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಹಂಪಿ, ಪಟ್ಟದಕಲ್ಲು, ಆಗ್ರಾದ ತಾಜ್‌ಮಹಲ್ ಮತ್ತು ಕೊನಾರ್ಕ್‌ನ ಸೂರ್ಯ ದೇವಾಲಯ." },
  { id: "U2_K03", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ಕಿ.ಉ", marks: 2, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿಶ್ಲೇಷಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ನೀವು ವಿಜ್ಞಾನಿಯಾದರೆ ಭಾರತ ದೇಶಕ್ಕೆ ಯಾವ ರೀತಿ ಕೊಡುಗೆ ನೀಡುತ್ತೀರಿ?", a: "ಹೊಸ ಆವಿಷ್ಕಾರಗಳ ಮೂಲಕ ದೇಶದ ಕೃಷಿ, ಆರೋಗ್ಯ ಕ್ಷೇತ್ರವನ್ನು ಉನ್ನತೀಕರಿಸಿ ಮಾನವಕುಲಕ್ಕೆ ಶಾಂತಿ ತರುವ ಸಂಶೋಧನೆಗಳಲ್ಲಿ ತೊಡಗುತ್ತೇನೆ." },
  { id: "U2_L01", unit: "ಭಾರತ ನಮ್ಮ ಹೆಮ್ಮೆ", type: "ವಿ.ಉ", marks: 4, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಭಾರತ ಉಪಖಂಡದ ಸಾಂಸ್ಕೃತಿಕ ಶ್ರೇಷ್ಠತೆಯ ಕುರಿತು ಟಿಪ್ಪಣಿ ಬರೆಯಿರಿ.", a: "ಭಾರತವು ಜಗತ್ತಿಗೆ ಸೊನ್ನೆ, ಗಣಿತ, ಖಗೋಳಶಾಸ್ತ್ರ, ಯೋಗ ಮತ್ತು ಸಂಸ್ಕೃತ ಸಾಹಿತ್ಯವನ್ನು ನೀಡಿದೆ. ಅಹಿಂಸೆ, 'ವಸುಧೈವ ಕುಟುಂಬಕಂ' (ಇಡೀ ಜಗತ್ತೇ ಒಂದು ಕುಟುಂಬ) ಮತ್ತು ಸರ್ವಧರ್ಮ ಸಮಾನತೆಯ ಆದರ್ಶಗಳು ಭಾರತದ ಹಿರಿಮೆಯನ್ನು ವಿಶ್ವದಲ್ಲೇ ಶ್ರೇಷ್ಠವಾಗಿಸಿವೆ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 3: ನಮ್ಮ ಹೆಮ್ಮೆಯ ರಾಜ್ಯ- ಕರ್ನಾಟಕ
  // ==========================================
  { id: "U3_F01", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕರ್ನಾಟಕದಲ್ಲಿ ವಿಸ್ತೀರ್ಣದಲ್ಲಿ ಅತಿ ದೊಡ್ಡ ಜಿಲ್ಲೆ ____________.", a: "ಬೆಳಗಾವಿ" },
  { id: "U3_F02", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕರ್ನಾಟಕದಲ್ಲಿ ವಿಸ್ತೀರ್ಣದಲ್ಲಿ ಅತಿ ಚಿಕ್ಕ ಜಿಲ್ಲೆ ____________.", a: "ಬೆಂಗಳೂರು ನಗರ" },
  { id: "U3_F03", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಸ್ತುತ ಕರ್ನಾಟಕದಲ್ಲಿರುವ ಒಟ್ಟು ಜಿಲ್ಲೆಗಳ ಸಂಖ್ಯೆ ____________.", a: "31" },
  { id: "U3_F04", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬೆಂಗಳೂರು ವಿಭಾಗದಲ್ಲಿ ಒಟ್ಟು ____________ ಜಿಲ್ಲೆಗಳಿವೆ.", a: "9" },
  { id: "U3_F05", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪಾಳೆಗಾರರು ಆಳುತ್ತಿದ್ದ ಸಣ್ಣ ಪ್ರದೇಶಗಳನ್ನು ____________ ಎನ್ನುತ್ತಿದ್ದರು.", a: "ಪಾಳೆಪಟ್ಟು" },
  { id: "U3_F06", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಮೈಸೂರು ವಿಭಾಗದಲ್ಲಿ ಒಟ್ಟು ____________ ಜಿಲ್ಲೆಗಳಿವೆ.", a: "8" },
  { id: "U3_F07", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕಲಬುರಗಿ ವಿಭಾಗದಲ್ಲಿ ಒಟ್ಟು ____________ ಜಿಲ್ಲೆಗಳಿವೆ.", a: "7" },
  { id: "U3_F08", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬೆಳಗಾವಿ ವಿಭಾಗದಲ್ಲಿ ಒಟ್ಟು ____________ ಜಿಲ್ಲೆಗಳಿವೆ.", a: "7" },
  { id: "U3_F09", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕರ್ನಾಟಕದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಅರಣ್ಯ ಹೊಂದಿರುವ ಜಿಲ್ಲೆ ____________.", a: "ಉತ್ತರ ಕನ್ನಡ" },
  { id: "U3_F10", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಒಣ ಮೆಣಸಿನಕಾಯಿಯ ಪ್ರಸಿದ್ಧ ವ್ಯಾಪಾರ ಮಾರುಕಟ್ಟೆ ಹಾವೇರಿ ಜಿಲ್ಲೆಯ ____________ ಯಲ್ಲಿದೆ.", a: "ಬ್ಯಾಡಗಿ" },
  { id: "U3_M01", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕರ್ನಾಟಕದಲ್ಲಿ ಅತಿ ಕಡಿಮೆ ಮಳೆ ಬೀಳುವ ಜಿಲ್ಲೆ ಯಾವುದು?", opts: ["ಚಿತ್ರದುರ್ಗ", "ಶಿವಮೊಗ್ಗ", "ಉಡುಪಿ", "ಕೊಡಗು"], a: "A) ಚಿತ್ರದುರ್ಗ" },
  { id: "U3_M02", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕದಂಬರ ರಾಜಧಾನಿ ಯಾವುದಾಗಿತ್ತು?", opts: ["ಮಾನ್ಯಖೇಟ", "ತಲಕಾಡು", "ಬನವಾಸಿ", "ದ್ವಾರಸಮುದ್ರ"], a: "C) ಬನವಾಸಿ" },
  { id: "U3_M03", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಮೈಸೂರಿನಲ್ಲಿ ನಡೆಯುವ ಜಗತ್ಪ್ರಸಿದ್ಧ ಜನಪ್ರಿಯ ಉತ್ಸವ ಯಾವುದು?", opts: ["ದಸರಾ ಉತ್ಸವ", "ಕರಗ", "ಹಂಪಿ ಉತ್ಸವ", "ಕದಂಬೋತ್ಸವ"], a: "A) ದಸರಾ ಉತ್ಸವ" },
  { id: "U3_S01", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕರ್ನಾಟಕದ ಅತಿ ಎತ್ತರವಾದ ಪರ್ವತ ಶಿಖರ ಯಾವುದು?", a: "ಮುಳ್ಳಯ್ಯನಗಿರಿ (ಚಿಕ್ಕಮಗಳೂರು)" },
  { id: "U3_S02", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಶರಾವತಿ ನದಿಯಿಂದ ನಿರ್ಮಾಣವಾದ ವಿಶ್ವವಿಖ್ಯಾತ ಜಲಪಾತ ಯಾವುದು?", a: "ಜೋಗ ಜಲಪಾತ (ಶಿವಮೊಗ್ಗ)" },
  { id: "U3_S03", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪೋರ್ಚುಗೀಸರ ವಿರುದ್ಧ ಕೆಚ್ಚೆದೆಯಿಂದ ಹೋರಾಡಿದ ಉಳ್ಳಾಲದ ವೀರರಾಣಿ ಯಾರು?", a: "ರಾಣಿ ಅಬ್ಬಕ್ಕದೇವಿ" },
  { id: "U3_S04", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಚಿನ್ನ ಉತ್ಪಾದಿಸುವ ಗಣಿ ಎಲ್ಲಿದೆ?", a: "ರಾಯಚೂರಿನ ಹಟ್ಟಿ ಚಿನ್ನದ ಗಣಿ" },
  { id: "U3_S05", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕೈಗಾ ಅಣು ವಿದ್ಯುತ್ ಸ್ಥಾವರ ಯಾವ ಜಿಲ್ಲೆಯಲ್ಲಿದೆ?", a: "ಉತ್ತರ ಕನ್ನಡ ಜಿಲ್ಲೆ" },
  { id: "U3_K01", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಕಾರಣೀಕರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಮೈಸೂರು ಎಂಬ ಹೆಸರು ಬರಲು ಐತಿಹಾಸಿಕ ಮತ್ತು ಪೌರಾಣಿಕ ಕಾರಣವೇನು?", a: "ಚಾಮುಂಡೇಶ್ವರಿ ದೇವಿಯು ಮಹಿಷಾಸುರನನ್ನು ಕೊಂದ ಸ್ಥಳ ಮಹಿಷನಾಡು ಎಂದಾಗಿ, ನಂತರ ಮೈಸೂರು ಎಂದು ರೂಪಾಂತರ ಹೊಂದಿತು." },
  { id: "U3_K02", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಬೆಂಗಳೂರು ವಿಭಾಗದ ಎರಡು ಪ್ರಮುಖ ಪಕ್ಷಿಧಾಮಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಗುಡವಿ ಪಕ್ಷಿಧಾಮ ಮತ್ತು ಮಂಡಗದ್ದೆ ಪಕ್ಷಿಧಾಮ (ಶಿವಮೊಗ್ಗ ಜಿಲ್ಲೆ)." },
  { id: "U3_K03", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಮೈಸೂರು ವಿಭಾಗದ ಎರಡು ಪ್ರಸಿದ್ಧ ರಾಷ್ಟ್ರೀಯ ಉದ್ಯಾನವನಗಳನ್ನು ತಿಳಿಸಿ.", a: "ನಾಗರಹೊಳೆ ರಾಷ್ಟ್ರೀಯ ಉದ್ಯಾನವನ ಮತ್ತು ಬಂಡೀಪುರ ರಾಷ್ಟ್ರೀಯ ಉದ್ಯಾನವನ." },
  { id: "U3_K04", unit: "ನಮ್ಮ ಹೆಮ್ಮೆಯ ಕರ್ನಾಟಕ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ನಿತ್ಯ ಹರಿದ್ವರ್ಣ ಕಾಡುಗಳು ಎಂದರೇನು?", a: "ಉಷ್ಣವಲಯದ ಅತಿ ಹೆಚ್ಚು ಮಳೆ ಬೀಳುವ ಹಾಗೂ ವರ್ಷವಿಡೀ ಹಸಿರಾಗಿ ಕಂಗೊಳಿಸುವ ದಟ್ಟ ಅರಣ್ಯಗಳಿಗೆ ನಿತ್ಯ ಹರಿದ್ವರ್ಣ ಕಾಡುಗಳು ಎನ್ನುವರು." },

  // ==========================================
  // ಅಧ್ಯಾಯ 4: ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ
  // ==========================================
  { id: "U4_F01", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಅತ್ಯಂತ ಪ್ರಾಚೀನ ವೇದ ____________.", a: "ಋಗ್ವೇದ" },
  { id: "U4_F02", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಋಗ್ವೇದದ ಕಾಲವನ್ನು ____________ ಎಂದು ಕರೆಯುತ್ತಾರೆ.", a: "ಪೂರ್ವ ವೇದಕಾಲ" },
  { id: "U4_F03", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಮಹಾಭಾರತ ಬರೆದ ಮಹರ್ಷಿ ____________.", a: "ವೇದವ್ಯಾಸರು" },
  { id: "U4_F04", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಉತ್ತರ ವೇದಗಳ ಕಾಲದಲ್ಲಿ ಕಣ್ಮರೆಯಾದ ಪ್ರಜಾಸತ್ತಾತ್ಮಕ ರಾಜಕೀಯ ಸಂಸ್ಥೆ ____________.", a: "ವಿಧಾತ" },
  { id: "U4_M01", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "'ವೇದ' ಪದದ ಮೂಲ ಅರ್ಥವೇನು?", opts: ["ಜ್ಞಾನ", "ಶಾಂತಿ", "ಯುದ್ಧ", "ಪ್ರಾರ್ಥನೆ"], a: "A) ಜ್ಞಾನ" },
  { id: "U4_S01", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಆರ್ಯರು ಎಲ್ಲಿಂದ ಭಾರತಕ್ಕೆ ವಲಸೆ ಬಂದರು?", a: "ಮಧ್ಯ ಏಷ್ಯಾ" },
  { id: "U4_S02", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ವೇದಗಳ ಸಾಹಿತ್ಯವು ಯಾವ ಪ್ರಾಚೀನ ಭಾಷೆಯಲ್ಲಿದೆ?", a: "ಸಂಸ್ಕೃತ ಭಾಷೆ" },
  { id: "U4_S03", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪೂರ್ವ ವೇದ ಕಾಲದಲ್ಲಿ ಸಮಾಜದ ಮೂಲ ಘಟಕ ಯಾವುದಾಗಿತ್ತು?", a: "ಕುಟುಂಬ" },
  { id: "U4_S04", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಆರ್ಯರ ಬಣದ ಮುಖ್ಯಸ್ಥನನ್ನು ಏನೆಂದು ಕರೆಯುತ್ತಿದ್ದರು?", a: "ರಾಜನ್" },
  { id: "U4_K01", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಭಾರತದ ನಾಲ್ಕು ಪವಿತ್ರ ವೇದಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಋಗ್ವೇದ, ಯಜುರ್ವೇದ, ಸಾಮವೇದ ಮತ್ತು ಅಥರ್ವಣ ವೇದ." },
  { id: "U4_K02", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ವೇದಕಾಲದ ಸಮಾಜದಲ್ಲಿದ್ದ ನಾಲ್ಕು ಆಶ್ರಮಗಳು ಯಾವುವು?", a: "ಬ್ರಹ್ಮಚರ್ಯ, ಗೃಹಸ್ಥ, ವಾನಪ್ರಸ್ಥ ಮತ್ತು ಸನ್ಯಾಸ." },
  { id: "U4_K03", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ವೇದಗಳ ಕಾಲದಲ್ಲಿದ್ದ ನಾಲ್ಕು ಪ್ರಮುಖ ವರ್ಣಗಳು ಯಾವುವು?", a: "ಬ್ರಾಹ್ಮಣ, ಕ್ಷತ್ರಿಯ, ವೈಶ್ಯ ಮತ್ತು ಶೂದ್ರ." },
  { id: "U4_K04", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 5, q: "ವೇದಕಾಲದ ಪ್ರಸಿದ್ಧ ವಿದುಷಿಯರನ್ನು (ಮಹಿಳಾ ವಿದ್ವಾಂಸರು) ಹೆಸರಿಸಿ.", a: "ಘೋಷಾ, ಅಪಾಲಾ, ಲೋಪಮುದ್ರಾ, ಇಂದ್ರಾಣಿ ಮತ್ತು ವಿಶ್ವವರಾ." },
  { id: "U4_K05", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಪೂರ್ವ ವೇದ ಕಾಲದ ಪ್ರಮುಖ ರಾಜಕೀಯ ಸಂಸ್ಥೆಗಳು ಯಾವುವು?", a: "ಸಭಾ, ಸಮಿತಿ ಮತ್ತು ವಿಧಾತ." },
  { id: "U4_K06", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಉತ್ತರ ವೇದ ಕಾಲದಲ್ಲಿ ರಾಜ್ಯ ವಿಸ್ತರಣೆಗಾಗಿ ನಡೆಸುತ್ತಿದ್ದ ಯಾಗಗಳು ಯಾವುವು?", a: "ಅಶ್ವಮೇಧ ಯಾಗ ಮತ್ತು ರಾಜಸೂಯ ಯಾಗ." },
  { id: "U4_K07", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ವೇದಗಳ ಉದಾತ್ತ ಸಂದೇಶವೇನು?", a: "ಸತ್ಯವು ಒಂದೇ ಆಗಿದೆ, ತಿಳಿದವರು ಅದನ್ನು ಹಲವು ರೀತಿಯಲ್ಲಿ ವರ್ಣಿಸುತ್ತಾರೆ. ಜಗತ್ತಿನ ಎಲ್ಲಾ ದಿಕ್ಕುಗಳಿಂದಲೂ ಶ್ರೇಷ್ಠ ವಿಚಾರಗಳು ನಮಗೆ ಬರಲಿ." },
  { id: "U4_L01", unit: "ವೇದಕಾಲದ ಸಂಸ್ಕೃತಿ", type: "ವಿ.ಉ", marks: 4, obj: "ತಿಳುವಳಿಕೆ", spec: "ವ್ಯತ್ಯಾಸೀಕರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಪೂರ್ವ ವೇದ ಕಾಲ ಮತ್ತು ಉತ್ತರ ವೇದ ಕಾಲದ ಸಮಾಜಕ್ಕಿರುವ ವ್ಯತ್ಯಾಸಗಳನ್ನು ತಿಳಿಸಿ.", a: "ಪೂರ್ವ ವೇದಕಾಲದಲ್ಲಿ ಸ್ತ್ರೀಯರಿಗೆ ಉನ್ನತ ಸ್ಥಾನಮಾನ, ವಿದ್ಯಾಭ್ಯಾಸದ ಹಕ್ಕಿತ್ತು; ಸಭಾ, ಸಮಿತಿ, ವಿಧಾತ ಸಂಸ್ಥೆಗಳಿದ್ದವು; ಬಾಲ್ಯವಿವಾಹವಿರಲಿಲ್ಲ. ಉತ್ತರ ವೇದಕಾಲದಲ್ಲಿ ಸ್ತ್ರೀಯರ ಸ್ಥಾನ ಕುಸಿಯಿತು; ಸತಿ ಸಹಗಮನ ಪದ್ಧತಿ ಆರಂಭವಾಯಿತು; ವಿಧಾತ ಕಣ್ಮರೆಯಾಗಿ ಧಾರ್ಮಿಕ ಆಚರಣೆಗಳು ಜಟಿಲವಾದವು." },

  // ==========================================
  // ಅಧ್ಯಾಯ 5: ಹೊಸ ಧರ್ಮಗಳ ಉದಯ
  // ==========================================
  { id: "U5_F01", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಗೌತಮ ಬುದ್ಧ ಜನಿಸಿದ ಸ್ಥಳ ನೇಪಾಳದ ಕಪಿಲವಸ್ತು ಸಮೀಪದ ____________.", a: "ಲುಂಬಿನಿ ವನ" },
  { id: "U5_F02", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಗೌತಮ ಬುದ್ಧನ ಬಾಲ್ಯದ ಹೆಸರು ____________.", a: "ಸಿದ್ಧಾರ್ಥ" },
  { id: "U5_F03", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬುದ್ಧನಿಗೆ ಜ್ಞಾನೋದಯವಾದ ಪವಿತ್ರ ಸ್ಥಳ ಬಿಹಾರದ ____________.", a: "ಗಯಾ (ಬೋಧಗಯಾ)" },
  { id: "U5_F04", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜೈನ ಧರ್ಮದ ಮೊದಲ ತೀರ್ಥಂಕರ ____________.", a: "ವೃಷಭನಾಥ" },
  { id: "U5_F05", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜೈನ ಧರ್ಮದ 23ನೇ ತೀರ್ಥಂಕರ ____________.", a: "ಪಾರ್ಶ್ವನಾಥ" },
  { id: "U5_M01", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜೈನ ಧರ್ಮದ 24ನೇ ತೀರ್ಥಂಕರ ಯಾರು?", opts: ["ವರ್ಧಮಾನ ಮಹಾವೀರ", "ಪಾರ್ಶ್ವನಾಥ", "ವೃಷಭನಾಥ", "ಗೌತಮ ಬುದ್ಧ"], a: "A) ವರ್ಧಮಾನ ಮಹಾವೀರ" },
  { id: "U5_M02", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬುದ್ಧನು ತನ್ನ ಮೊದಲ ಧರ್ಮೋಪದೇಶವನ್ನು ನೀಡಿದ ಸ್ಥಳ:", opts: ["ಸಾರನಾಥ", "ಗಯಾ", "ಲುಂಬಿನಿ", "ಕುಂದಗ್ರಾಮ"], a: "A) ಸಾರನಾಥ" },
  { id: "U5_S01", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬೌದ್ಧ ಧರ್ಮದ ಸಂಸ್ಥಾಪಕರು ಯಾರು?", a: "ಗೌತಮ ಬುದ್ಧ" },
  { id: "U5_S02", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "'ಜಿನ' ಎಂಬ ಪದದ ಅರ್ಥವೇನು?", a: "ತನ್ನ ಆಸೆ, ಮೋಹ ಮತ್ತು ಇಂದ್ರಿಯಗಳನ್ನು ಗೆದ್ದವನು." },
  { id: "U5_S03", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬುದ್ಧ ಪದದ ಅರ್ಥವೇನು?", a: "ಜ್ಞಾನೋದಯ ಹೊಂದಿದವನು ಅಥವಾ ಎಚ್ಚರಗೊಂಡವನು." },
  { id: "U5_S04", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಶ್ವೇತಾಂಬರರು ಎಂದರೆ ಯಾರು?", a: "ಬಿಳಿಯ ವಸ್ತ್ರವನ್ನು ಧರಿಸುವ ಪಾರ್ಶ್ವನಾಥನ ಅನುಯಾಯಿಗಳು." },
  { id: "U5_K01", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಗೌತಮ ಬುದ್ಧನ ಬೋಧನೆಗಳ ತಿರುಳು ಏನು?", a: "ಜಗತ್ತು ಅಪಾರ ದುಃಖಮಯವಾಗಿದೆ; ಆಸೆಯೇ ದುಃಖಕ್ಕೆ ಮೂಲ; ಆಸೆಯನ್ನು ಗೆದ್ದವರು ನಿರ್ವಾಣ ಹೊಂದುವರು; ದುಃಖ ನಿವಾರಣೆಗೆ ಅಷ್ಟಾಂಗ ಮಾರ್ಗ ಅವಶ್ಯಕ." },
  { id: "U5_K02", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಮಹಾವೀರನ ಪಂಚ ತತ್ವಗಳನ್ನು ತಿಳಿಸಿ.", a: "ಹಿಂಸೆ ಮಾಡದಿರುವುದು, ಸುಳ್ಳು ಹೇಳದಿರುವುದು, ಕಳ್ಳತನ ಮಾಡದಿರುವುದು, ಸಂಪತ್ತಿನ ಅತಿಯಾದ ಸಂಗ್ರಹ ಮಾಡದಿರುವುದು ಮತ್ತು ಬ್ರಹ್ಮಚರ್ಯ ಪಾಲನೆ." },
  { id: "U5_K03", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಬುದ್ಧನ ಮನಪರಿವರ್ತನೆಗೆ ಕಾರಣವಾದ ನಾಲ್ಕು ಸನ್ನಿವೇಶಗಳು ಯಾವುವು?", a: "ಒಬ್ಬ ವೃದ್ಧ, ರೋಗಿ, ಶವ ಯಾತ್ರೆ ಮತ್ತು ಪ್ರಶಾಂತ ಸನ್ಯಾಸಿ." },
  { id: "U5_K04", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಬೌದ್ಧರ ಪವಿತ್ರ ಗ್ರಂಥಗಳಾದ ತ್ರಿಪಿಟಕಗಳು ಯಾವುವು?", a: "ವಿನಯ ಪೀಟಕ, ಸುತ್ತ ಪೀಟಕ ಮತ್ತು ಅಭಿಧಮ್ಮ ಪೀಟಕ." },
  { id: "U5_L01", unit: "ಹೊಸ ಧರ್ಮಗಳ ಉದಯ", type: "ವಿ.ಉ", marks: 4, obj: "ತಿಳುವಳಿಕೆ", spec: "ವ್ಯತ್ಯಾಸೀಕರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಜೈನ ಧರ್ಮದ ಶ್ವೇತಾಂಬರ ಮತ್ತು ದಿಗಂಬರ ಪಂಥಗಳ ನಡುವಿನ ವ್ಯತ್ಯಾಸ ತಿಳಿಸಿ.", a: "ಶ್ವೇತಾಂಬರರು ಬಿಳಿ ವಸ್ತ್ರ ಧರಿಸುತ್ತಾರೆ, ಮಹಿಳೆಯರಿಗೆ ಇದೇ ಜನ್ಮದಲ್ಲಿ ಮೋಕ್ಷ ಸಾಧ್ಯವೆನ್ನುತ್ತಾರೆ. ದಿಗಂಬರರು ಸಂಪೂರ್ಣ ವಸ್ತ್ರರಹಿತರಾಗಿರುತ್ತಾರೆ ಹಾಗೂ ಮಹಿಳೆಯರು ಮೋಕ್ಷಕ್ಕಾಗಿ ಮುಂದಿನ ಜನ್ಮದಲ್ಲಿ ಪುರುಷರಾಗಿ ಜನಿಸಬೇಕೆಂದು ನಂಬುತ್ತಾರೆ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 6: ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು
  // ==========================================
  { id: "U6_F01", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ತಮಿಳಿನ ಶ್ರೇಷ್ಠ ನೀತಿ ಗ್ರಂಥ 'ತಿರುಕ್ಕುರಳ್' ಕೃತಿಯ ರಚನಾಕಾರರು ____________.", a: "ತಿರುವಳ್ಳುವರ್" },
  { id: "U6_F02", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಶಾತವಾಹನರ ಮೊದಲ ರಾಜಧಾನಿ ____________.", a: "ಪ್ರತಿಷ್ಠಾನಪುರ" },
  { id: "U6_F03", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕನ್ನಡದ ಮೊದಲ ರಾಜಮನೆತನ ____________.", a: "ಕದಂಬರು" },
  { id: "U6_F04", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕನ್ನಡದ ಮೊದಲ ಶಿಲಾಶಾಸನ ____________.", a: "ಹಲ್ಮಿಡಿ ಶಾಸನ" },
  { id: "U6_F05", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಬಾದಾಮಿ ಚಾಲುಕ್ಯರ ಶ್ರೇಷ್ಠ ಚಕ್ರವರ್ತಿ ____________.", a: "ಇಮ್ಮಡಿ ಪುಲಕೇಶಿ" },
  { id: "U6_F06", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "'ದೇವಾಲಯಗಳ ವಾಸ್ತುಶಿಲ್ಪದ ತೊಟ್ಟಿಲು' ಎಂದು ____________ ನ್ನು ಕರೆಯುತ್ತಾರೆ.", a: "ಐಹೊಳೆ" },
  { id: "U6_M01", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪಲ್ಲವರ ರಾಜಧಾನಿ ಕಂಚಿ ಪ್ರಸ್ತುತ ಈ ಕೆಳಗಿನ ಯಾವ ರಾಜ್ಯದಲ್ಲಿದೆ?", opts: ["ಕರ್ನಾಟಕ", "ಮಹಾರಾಷ್ಟ್ರ", "ತಮಿಳುನಾಡು", "ಕೇರಳ"], a: "C. ತಮಿಳುನಾಡು" },
  { id: "U6_M02", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "'ಮಾನಸೋಲ್ಲಾಸ' ಕೃತಿಯನ್ನು ರಚಿಸಿದ ಕಲ್ಯಾಣಿ ಚಾಲುಕ್ಯ ದೊರೆ:", opts: ["ಮುಮ್ಮಡಿ ಸೋಮೇಶ್ವರ", "ಆರನೇ ವಿಕ್ರಮಾದಿತ್ಯ", "ದುರ್ವಿನೀತ", "ಅಮೋಘವರ್ಷ"], a: "A) ಮುಮ್ಮಡಿ ಸೋಮೇಶ್ವರ" },
  { id: "U6_M03", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಹೊಯ್ಸಳ ಸಾಮ್ರಾಜ್ಯದ ಕೊನೆಯ ಪ್ರಸಿದ್ಧ ರಾಜ:", opts: ["ವಿಷ್ಣುವರ್ಧನ", "ಮೂರನೇ ಬಲ್ಲಾಳ", "ಮೂರನೇ ಗೋವಿಂದ", "ಮೂರನೇ ಕೃಷ್ಣ"], a: "B) ಮೂರನೇ ಬಲ್ಲಾಳ" },
  { id: "U6_S01", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಗೌತಮಿಪುತ್ರ ಶಾತಕರ್ಣಿಗಿದ್ದ ಬಿರುದು ಯಾವುದು?", a: "ತ್ರೈಸಮುದ್ರ ತೋಯ ಪೀತ ವಾಹನ" },
  { id: "U6_S02", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಕದಂಬರ ರಾಜಧಾನಿ ಯಾವುದಾಗಿತ್ತು?", a: "ಬನವಾಸಿ (ಉತ್ತರ ಕನ್ನಡ ಜಿಲ್ಲೆ)" },
  { id: "U6_S03", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಶ್ರವಣಬೆಳಗೊಳದ ಗೊಮ್ಮಟೇಶ್ವರ ಮೂರ್ತಿಯನ್ನು ಕೆತ್ತಿಸಿದವರು ಯಾರು?", a: "ಗಂಗರ ಮಂತ್ರಿ ಚಾವುಂಡರಾಯ (ಕ್ರಿ.ಶ. 981)" },
  { id: "U6_S04", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಇಮ್ಮಡಿ ಪುಲಕೇಶಿಯ ಸಾಧನೆಗಳನ್ನು ವರ್ಣಿಸುವ ಶಾಸನ ಯಾವುದು?", a: "ರವಿಕೀರ್ತಿ ರಚಿಸಿದ ಐಹೊಳೆ ಶಾಸನ" },
  { id: "U6_S05", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಎಲ್ಲೋರಾದ ಕೈಲಾಸನಾಥ ದೇವಾಲಯವನ್ನು ಕೆತ್ತಿಸಿದ ರಾಷ್ಟ್ರಕೂಟ ದೊರೆ ಯಾರು?", a: "ಒಂದನೆಯ ಕೃಷ್ಣ" },
  { id: "U6_K01", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಕಾರಣೀಕರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಎಲ್ಲೋರಾದ ಕೈಲಾಸ ದೇವಾಲಯ ಮತ್ತು ಎಲಿಫೆಂಟಾ ಗುಹಾಲಯ ಏಕೆ ಪ್ರಸಿದ್ಧವಾಗಿವೆ?", a: "ಕೈಲಾಸನಾಥ ದೇವಾಲಯವು ಒಂದೇ ಬೃಹತ್ ಬೆಟ್ಟದ ಬಂಡೆಯನ್ನು ಕೆತ್ತಿ ನಿರ್ಮಿಸಿದ ಏಕಶಿಲಾ ಅದ್ಭುತ; ಎಲಿಫೆಂಟಾದಲ್ಲಿ ಮೂರು ಮುಖವುಳ್ಳ ಭವ್ಯ ತ್ರಿಮೂರ್ತಿ ಶಿವನ ಶಿಲ್ಪವಿದೆ." },
  { id: "U6_K02", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಹೊಯ್ಸಳರ ಕಾಲದ ವಾಸ್ತುಶಿಲ್ಪದ ಪ್ರಮುಖ ಲಕ್ಷಣಗಳನ್ನು ತಿಳಿಸಿ.", a: "ನಕ್ಷತ್ರಾಕಾರದ ಜಗತಿ, ಗರ್ಭಗೃಹ, ಸುಖನಾಸಿ, ನವರಂಗ, ಕಲಾತ್ಮಕ ಭುವನೇಶ್ವರಿ ಮತ್ತು ಸೂಕ್ಷ್ಮ ಕೆತ್ತನೆಯ ಮದನಿಕಾ ವಿಗ್ರಹಗಳು." },
  { id: "U6_K03", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "'ದೇವಾಲಯಗಳ ಚಕ್ರವರ್ತಿ' ಎಂದು ಯಾವ ದೇವಾಲಯವನ್ನು ಕರೆಯಲಾಗುತ್ತದೆ? ಏಕೆ?", a: "ಕೊಪ್ಪಳ ಜಿಲ್ಲೆಯ ಇಟಗಿಯ ಮಹಾದೇವ ದೇವಾಲಯವನ್ನು ಕಲ್ಯಾಣಿ ಚಾಲುಕ್ಯರ ಅಪ್ರತಿಮ ವಾಸ್ತುಶಿಲ್ಪ ಸೌಂದರ್ಯ ಮತ್ತು ಶಾಸನದ ಉಲ್ಲೇಖದ ಕಾರಣದಿಂದ 'ದೇವಾಲಯಗಳ ಚಕ್ರವರ್ತಿ' ಎನ್ನುವರು." },
  { id: "U6_L01", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವಿ.ಉ", marks: 4, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ಸಮರ್ಥಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಚೋಳರ ಕಾಲದ ಗ್ರಾಮ ಆಡಳಿತ ವ್ಯವಸ್ಥೆಯನ್ನು ವಿವರಿಸಿ.", a: "ಗ್ರಾಮಗಳಲ್ಲಿ ಸ್ವಾಯತ್ತ ಗ್ರಾಮಸಭೆಗಳಿದ್ದವು; ಕುಡುವಲೈ (ಲಾಟರಿ) ಪದ್ಧತಿಯ ಮೂಲಕ ಅರ್ಹ ಗ್ರಾಮಸ್ಥರನ್ನು ಸದಸ್ಯರನ್ನಾಗಿ ಚುನಾಯಿಸಲಾಗುತ್ತಿತ್ತು; ಕೆರೆ, ತೋಟ, ಆಡಳಿತ ಸಮಿತಿಗಳನ್ನು ರಚಿಸಿ ಪಾರದರ್ಶಕವಾಗಿ ಲೆಕ್ಕ ಒಪ್ಪಿಸಲಾಗುತ್ತಿತ್ತು. ಇದು ಇಂದಿನ ಗ್ರಾಮ ಪಂಚಾಯಿತಿಗೆ ತಳಪಾಯವಾಗಿದೆ." },
  { id: "U6_L02", unit: "ದಕ್ಷಿಣ ಭಾರತದ ಪ್ರಾಚೀನ ರಾಜವಂಶಗಳು", type: "ವಿ.ಉ", marks: 4, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ತಂಜಾವೂರಿನ ಬೃಹದೀಶ್ವರ ದೇವಾಲಯವು ಜಗತ್ಪ್ರಸಿದ್ಧವಾಗಲು ಕಾರಣವಾದ ಅಂಶಗಳೇನು?", a: "ಮೊದಲ ರಾಜರಾಜ ಚೋಳನು ಸಂಪೂರ್ಣ ಗ್ರಾನೈಟ್ ಶಿಲೆಗಳಿಂದ ನಿರ್ಮಿಸಿದನು. ಇದರ 216 ಅಡಿ ಎತ್ತರದ ಭವ್ಯ ವಿಮಾನ (ಗೋಪುರ), ಅದರ ತುದಿಯಲ್ಲಿರುವ 80 ಟನ್ ತೂಕದ ಏಕಶಿಲಾ ಶಿಖರ, ಬೃಹತ್ ನಂದಿ ವಿಗ್ರಹ ಮತ್ತು ಯುನೆಸ್ಕೋ ಮಾನ್ಯತೆಯು ಇದನ್ನು ವಿಶ್ವದ ಅದ್ಭುತವಾಗಿಸಿದೆ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 7: ಪೌರ ಮತ್ತು ಪೌರತ್ವ
  // ==========================================
  { id: "U7_F01", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಒಂದು ದೇಶದ ಶಾಸನಾತ್ಮಕ ಸದಸ್ಯತ್ವವನ್ನು ____________ ಎನ್ನುತ್ತೇವೆ.", a: "ಪೌರತ್ವ" },
  { id: "U7_F02", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ದೇಶವೊಂದರಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ನೆಲೆಸಿರುವ ಜವಾಬ್ದಾರಿಯುತ ಸದಸ್ಯರನ್ನು ____________ ಎನ್ನುತ್ತೇವೆ.", a: "ಪೌರರು" },
  { id: "U7_S01", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ವಿದೇಶಿಯರು ಎಂದರೆ ಯಾರು?", a: "ಬೇರೆ ದೇಶದ ನಿವಾಸಿಗಳಾಗಿದ್ದು ನಮ್ಮ ದೇಶದಲ್ಲಿ ತಾತ್ಕಾಲಿಕವಾಗಿ ವಾಸಿಸುವವರನ್ನು ವಿದೇಶಿಯರು ಎನ್ನುವರು." },
  { id: "U7_S02", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪೌರತ್ವವನ್ನು ಪಡೆಯುವ ಎರಡು ಮುಖ್ಯ ವಿಧಾನಗಳು ಯಾವುವು?", a: "1) ಸಹಜ ಪೌರತ್ವ 2) ಸಹಜೀಕೃತ ಪೌರತ್ವ." },
  { id: "U7_S03", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಹಜ ಪೌರತ್ವದ ಎರಡು ವಿಧಾನಗಳು ಯಾವುವು?", a: "ಜನನದ ಮೂಲಕ ಮತ್ತು ವಂಶ ಪಾರಂಪರ್ಯದ ಮೂಲಕ." },
  { id: "U7_K01", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಪಟ್ಟಿ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ನೀವು ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ವಿದೇಶಿ ಎಂದು ಹೇಗೆ ಗುರುತಿಸುವಿರಿ?", a: "ಮುಖಚಹರೆ, ಮೈಕಟ್ಟು, ಭಾಷೆ, ಉಡುಗೆ-ತೊಡುಗೆ, ಜೀವನಶೈಲಿ ಮತ್ತು ಅಧಿಕೃತ ಪಾಸ್‌ಪೋರ್ಟ್/ವೀಸಾ ಆಧಾರದ ಮೇಲೆ." },
  { id: "U7_K02", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಪಟ್ಟಿ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಒಂದು ದೇಶದ ಪೌರತ್ವವನ್ನು ಕಳೆದುಕೊಳ್ಳುವ ವಿಧಾನಗಳು ಯಾವುವು?", a: "1) ಪರಿತ್ಯಾಗ (ಸ್ವಇಚ್ಛೆಯಿಂದ ಬಿಡುವುದು) 2) ಅಂತ್ಯಗೊಳ್ಳುವಿಕೆ (ಬೇರೆ ದೇಶದ ಪೌರತ್ವ ಪಡೆದಾಗ) 3) ನಿರಾಕರಣೆ (ಸರ್ಕಾರ ರದ್ದುಪಡಿಸುವುದು)." },
  { id: "U7_K03", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ಕಿ.ಉ", marks: 2, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿಶ್ಲೇಷಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಹಿರಿಯ ನಾಗರಿಕರಿಗೆ ನಾವು ಯಾವ ಯಾವ ರೀತಿಗಳಲ್ಲಿ ಸಹಾಯ ಮಾಡಬಹುದು?", a: "ರಸ್ತೆ ದಾಟಲು ನೆರವು ನೀಡುವುದು, ಸಾರಿಗೆ ವಾಹನಗಳಲ್ಲಿ ಆಸನ ಬಿಟ್ಟುಕೊಡುವುದು, ಗೌರವದಿಂದ ಮಾತನಾಡುವುದು ಮತ್ತು ಡಿಜಿಟಲ್ ತಂತ್ರಜ್ಞಾನ ಬಳಕೆಯಲ್ಲಿ ಸಹಾಯ ಮಾಡುವುದು." },
  { id: "U7_L01", unit: "ಪೌರ ಮತ್ತು ಪೌರತ್ವ", type: "ವಿ.ಉ", marks: 4, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿಶ್ಲೇಷಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 8, q: "ಭಾರತದ ಜವಾಬ್ದಾರಿಯುತ ಪೌರನಾಗಿ ನೀವು ನಿರ್ವಹಿಸಬೇಕಾದ ಕರ್ತವ್ಯಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ.", a: "ಸಂವಿಧಾನ, ರಾಷ್ಟ್ರಧ್ವಜ ಮತ್ತು ರಾಷ್ಟ್ರಗೀತೆಯನ್ನು ಗೌರವಿಸುವುದು; ಪರಿಸರ ಹಾಗೂ ಸಾರ್ವಜನಿಕ ಆಸ್ತಿಯನ್ನು ರಕ್ಷಿಸುವುದು; ಚುನಾವಣೆಯಲ್ಲಿ ಮತ ಚಲಾಯಿಸುವುದು; ನಿಯಮಿತವಾಗಿ ತೆರಿಗೆ ಪಾವತಿಸುವುದು ಮತ್ತು ದೇಶದ ಏಕತೆ-ಸಮಗ್ರತೆಯನ್ನು ಕಾಪಾಡುವುದು." },

  // ==========================================
  // ಅಧ್ಯಾಯ 8: ನಮ್ಮ ಸಂವಿಧಾನ
  // ==========================================
  { id: "U8_F01", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ರಾಷ್ಟ್ರೀಯ ಸಂವಿಧಾನ ದಿನವನ್ನು ಪ್ರತಿವರ್ಷ ____________ ರಂದು ಆಚರಿಸಲಾಗುತ್ತದೆ.", a: "ನವೆಂಬರ್ 26" },
  { id: "U8_F02", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂವಿಧಾನ ಕರಡು ಸಮಿತಿಯ ಅಧ್ಯಕ್ಷರು ____________.", a: "ಡಾ. ಬಿ.ಆರ್. ಅಂಬೇಡ್ಕರ್" },
  { id: "U8_F03", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತ ಸಂವಿಧಾನ ರಚನಾ ಸಭೆಯ ಕಾಯಂ ಅಧ್ಯಕ್ಷರು ____________.", a: "ಡಾ. ಬಾಬು ರಾಜೇಂದ್ರ ಪ್ರಸಾದ್" },
  { id: "U8_F04", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತದಲ್ಲಿ ಮತದಾನದ ಕನಿಷ್ಠ ವಯೋಮಿತಿ ____________ ವರ್ಷ.", a: "18" },
  { id: "U8_F05", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂವಿಧಾನದ ಪ್ರಸ್ತಾವನೆಯನ್ನು ಸಂವಿಧಾನದ ____________ ಎಂದು ಕರೆಯಲಾಗಿದೆ.", a: "ಹೃದಯ / ಕೈಗನ್ನಡಿ" },
  { id: "U8_M01", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂವಿಧಾನವು ಅಂತಿಮ ರೂಪ ಪಡೆಯಲು ತೆಗೆದುಕೊಂಡ ಒಟ್ಟು ಸಮಯ:", opts: ["2 ವರ್ಷ 10 ತಿಂಗಳು 18 ದಿನಗಳು", "2 ವರ್ಷ 9 ತಿಂಗಳು 18 ದಿನಗಳು", "2 ವರ್ಷ 11 ತಿಂಗಳು 17 ದಿನಗಳು", "2 ವರ್ಷ 11 ತಿಂಗಳು 18 ದಿನಗಳು"], a: "D. 2 ವರ್ಷ 11 ತಿಂಗಳು 18 ದಿನಗಳು" },
  { id: "U8_M02", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತದ ಸಂವಿಧಾನವು ಅಧಿಕೃತವಾಗಿ ಜಾರಿಗೆ ಬಂದ ದಿನ:", opts: ["ಜನವರಿ 26, 1950", "ಆಗಸ್ಟ್ 15, 1947", "ನವೆಂಬರ್ 26, 1949", "ಜನವರಿ 25, 1950"], a: "A. ಜನವರಿ 26, 1950" },
  { id: "U8_M03", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 2, q: "ಮೂಲಭೂತ ಹಕ್ಕುಗಳು ಉಲ್ಲಂಘನೆಯಾದಾಗ ಅವುಗಳನ್ನು ರಕ್ಷಿಸುವ ಅಧಿಕಾರ ಇರುವುದು:", opts: ["ಶಾಸಕಾಂಗ", "ಪೊಲೀಸ್ ಇಲಾಖೆ", "ರಕ್ಷಣಾಪಡೆ", "ನ್ಯಾಯಾಂಗ"], a: "D. ನ್ಯಾಯಾಂಗ" },
  { id: "U8_M04", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 2, q: "ಜಾತ್ಯತೀತತೆ ಎಂದರೆ:", opts: ["ರಾಜ್ಯ ಧರ್ಮದ ಹೆಸರಿನಲ್ಲಿ ಪಕ್ಷಪಾತ ಮಾಡುವುದು", "ಒಂದು ಧರ್ಮವನ್ನು ರಾಷ್ಟ್ರಧರ್ಮ ಮಾಡುವುದು", "ಎಲ್ಲ ಮತಧರ್ಮಗಳನ್ನು ಸಮಾನ ದೃಷ್ಟಿಯಿಂದ ನೋಡುವುದು", "ಯಾವುದೂ ಅಲ್ಲ"], a: "C. ಎಲ್ಲ ಮತಧರ್ಮಗಳನ್ನು ಸಮಾನ ದೃಷ್ಟಿಯಿಂದ ನೋಡುವುದು" },
  { id: "U8_S01", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂವಿಧಾನ ಎಂದರೇನು?", a: "ಒಂದು ದೇಶದ ಆಡಳಿತಕ್ಕೆ ನಿಯಮ ಮತ್ತು ಕಾಯಿದೆಗಳ ಚೌಕಟ್ಟು ಒದಗಿಸುವ ಸರ್ವಶ್ರೇಷ್ಠ ಕಾನೂನು ದಾಖಲೆ." },
  { id: "U8_S02", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಂಸತ್ತಿನಲ್ಲಿರುವ ಎರಡು ಸದನಗಳು ಯಾವುವು?", a: "ಲೋಕಸಭೆ ಮತ್ತು ರಾಜ್ಯಸಭೆ." },
  { id: "U8_S03", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಗಣರಾಜ್ಯ ಎಂದರೇನು?", a: "ಪ್ರಜೆಗಳಿಂದ ಚುನಾಯಿತರಾದ ಮುಖ್ಯಸ್ಥರಿರುವ ಮತ್ತು ಪ್ರಜೆಗಳ ಪ್ರತಿನಿಧಿಗಳ ಆಳ್ವಿಕೆ ಇರುವ ವ್ಯವಸ್ಥೆಯೇ ಗಣರಾಜ್ಯ." },
  { id: "U8_S04", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸುಖಿರಾಜ್ಯ ಎಂದರೇನು?", a: "ಸಾಮಾಜಿಕ ಮತ್ತು ಆರ್ಥಿಕ ಅವಕಾಶ ಹಾಗೂ ಭದ್ರತೆಯನ್ನು ಎಲ್ಲ ಪ್ರಜೆಗಳಿಗೂ ನೀಡುವ ಗುರಿ ಹೊಂದಿರುವ ರಾಜ್ಯ." },
  { id: "U8_K01", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಮೂಲಭೂತ ಹಕ್ಕುಗಳು ಹೇಗೆ ವಿಶೇಷವಾಗಿವೆ?", a: "ಮೂಲಭೂತ ಹಕ್ಕುಗಳನ್ನು ಯಾವುದೇ ಸರ್ಕಾರ ಮೊಟಕುಗೊಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ; ಇವುಗಳ ಉಲ್ಲಂಘನೆಯಾದಾಗ ಪ್ರಜೆಗಳು ನ್ಯಾಯಾಲಯದ ರಕ್ಷಣೆ ಪಡೆಯಬಹುದು." },
  { id: "U8_K02", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 5, q: "ಸಾರ್ವತ್ರಿಕ ವಯಸ್ಕ ಮತದಾನ ಪದ್ಧತಿ ಎಂದರೇನು?", a: "18 ವರ್ಷ ತುಂಬಿದ ಭಾರತದ ಎಲ್ಲಾ ನಾಗರಿಕರಿಗೆ ಜಾತಿ, ಮತ, ಲಿಂಗ ಭೇದವಿಲ್ಲದೆ ಚುನಾವಣೆಗಳಲ್ಲಿ ಮತ ಚಲಾಯಿಸುವ ಹಕ್ಕು ನೀಡುವುದೇ ಸಾರ್ವತ್ರಿಕ ವಯಸ್ಕ ಮತದಾನ ಪದ್ಧತಿ." },
  { id: "U8_K03", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಸಂವಿಧಾನದ ಮಹತ್ವವನ್ನು ತಿಳಿಸಿ.", a: "ಸಂವಿಧಾನವು ಜನತೆಯ ಆದರ್ಶಗಳನ್ನು ಪ್ರತಿಬಿಂಬಿಸುತ್ತದೆ, ಸುಖಿರಾಜ್ಯ ಸ್ಥಾಪನೆಗೆ ನಿರ್ದೇಶನ ನೀಡುತ್ತದೆ ಮತ್ತು ಸರ್ಕಾರದ ಅಧಿಕಾರವನ್ನು ನಿಯಂತ್ರಿಸಿ ಪ್ರಜೆಗಳ ಹಕ್ಕು ರಕ್ಷಿಸುತ್ತದೆ." },
  { id: "U8_L01", unit: "ನಮ್ಮ ಸಂವಿಧಾನ", type: "ವಿ.ಉ", marks: 4, obj: "ಜ್ಞಾನ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ನಮ್ಮ ಸಂವಿಧಾನದ ಪ್ರಮುಖ ಲಕ್ಷಣಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ ವಿವರಿಸಿ.", a: "1) ವಿಶ್ವದಲ್ಲೇ ಅತಿ ಸುದೀರ್ಘ ಲಿಖಿತ ಸಂವಿಧಾನ 2) ಪ್ರಜಾಸತ್ತಾತ್ಮಕ ಗಣರಾಜ್ಯ 3) ಮೂಲಭೂತ ಹಕ್ಕುಗಳು ಮತ್ತು ಕರ್ತವ್ಯಗಳು 4) ಜಾತ್ಯತೀತ ತತ್ವ 5) ಸ್ವತಂತ್ರ ನ್ಯಾಯಾಂಗ 6) ಸಾರ್ವತ್ರಿಕ ವಯಸ್ಕ ಮತದಾನ ಪದ್ಧತಿ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 9: ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು
  // ==========================================
  { id: "U9_F01", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಜನರಿಂದ ಆಯ್ಕೆಯಾದ ಪ್ರತಿನಿಧಿಗಳ ಮೂಲಕ ನಡೆಯುವ ಆಡಳಿತವನ್ನು ____________ ಎನ್ನುವರು.", a: "ಪ್ರಜಾಪ್ರಭುತ್ವ ಸರ್ಕಾರ" },
  { id: "U9_F02", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸರ್ವಾಧಿಕಾರಿ ಪ್ರಭುತ್ವಕ್ಕೆ ಜರ್ಮನಿಯ ____________ ನ ಆಡಳಿತ ಉದಾಹರಣೆ.", a: "ಹಿಟ್ಲರ್" },
  { id: "U9_F03", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಸಮತಾವಾದಿ ಸರ್ಕಾರ ವ್ಯವಸ್ಥೆಯ ಪ್ರತಿಪಾದಕರು ____________.", a: "ಕಾರ್ಲ್ ಮಾರ್ಕ್ಸ್" },
  { id: "U9_M01", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "'ಪ್ರಜೆಗಳಿಂದ, ಪ್ರಜೆಗಳಿಗಾಗಿ, ಪ್ರಜೆಗಳಿಗೋಸ್ಕರ ಇರುವ ಸರ್ಕಾರವೇ ಪ್ರಜಾಪ್ರಭುತ್ವ' ಎಂದವರು:", opts: ["ಅಬ್ರಹಂ ಲಿಂಕನ್", "ಮಹಾತ್ಮಾ ಗಾಂಧೀಜಿ", "ಕಾರ್ಲ್ ಮಾರ್ಕ್ಸ್", "ವಿನ್‌ಸ್ಟನ್ ಚರ್ಚಿಲ್"], a: "A) ಅಬ್ರಹಂ ಲಿಂಕನ್" },
  { id: "U9_S01", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಭುತ್ವ ಎಂದರೇನು?", a: "ಆಡಳಿತ ವ್ಯವಸ್ಥೆಯನ್ನು ನಿಯಮಾನುಸಾರ ಮುಂದುವರಿಸಿಕೊಂಡು ಹೋಗುವ ಅಧಿಕಾರ ಹೊಂದಿರುವ ವ್ಯವಸ್ಥೆಯೇ ಪ್ರಭುತ್ವ." },
  { id: "U9_S02", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಭುತ್ವದ ಮೂರು ಪ್ರಮುಖ ಪ್ರಕಾರಗಳು ಯಾವುವು?", a: "1) ಪ್ರಜಾಪ್ರಭುತ್ವ ಸರ್ಕಾರ 2) ಸರ್ವಾಧಿಕಾರಿ ಸರ್ಕಾರ 3) ಸಮತಾವಾದಿ ಸರ್ಕಾರ." },
  { id: "U9_K01", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಕಾರಣೀಕರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಪ್ರಜಾಪ್ರಭುತ್ವ ಸರ್ಕಾರವನ್ನು ಪ್ರಜೆಗಳ ಸರ್ಕಾರವೆಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?", a: "ಪ್ರಜಾಪ್ರಭುತ್ವದಲ್ಲಿ ಜನಬೆಂಬಲದಿಂದ ಪ್ರಜೆಗಳೇ ಪ್ರಭುಗಳಾಗಿ ಆಡಳಿತ ನಡೆಸುತ್ತಾರೆ ಹಾಗೂ ತಮ್ಮ ಪ್ರತಿನಿಧಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡುವ ಸಂಪೂರ್ಣ ಸ್ವಾತಂತ್ರ್ಯ ಹೊಂದಿರುತ್ತಾರೆ." },
  { id: "U9_K02", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಸಮತಾವಾದಿ ಸರ್ಕಾರ ಎಂದರೇನು?", a: "ಸಮಾಜದಲ್ಲಿರುವ ಉತ್ಪಾದನಾ ಮೂಲಗಳಾದ ಭೂಮಿ, ಶ್ರಮ, ಬಂಡವಾಳ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿದ್ದು, ಪ್ರತಿಯೊಬ್ಬರೂ ಸಾಮರ್ಥ್ಯಾನುಸಾರ ದುಡಿದು ಅಗತ್ಯಾನುಸಾರ ಪಡೆಯುವ ವ್ಯವಸ್ಥೆಯೇ ಸಮತಾವಾದಿ ಸರ್ಕಾರ." },
  { id: "U9_L01", unit: "ಪ್ರಭುತ್ವದ ಪ್ರಕಾರಗಳು", type: "ವಿ.ಉ", marks: 4, obj: "ತಿಳುವಳಿಕೆ", spec: "ವ್ಯತ್ಯಾಸೀಕರಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಪ್ರಜಾಪ್ರಭುತ್ವ ಸರ್ಕಾರ ಹಾಗೂ ಸರ್ವಾಧಿಕಾರಿ ಸರ್ಕಾರದ ನಡುವಿನ ಭಿನ್ನತೆಗಳನ್ನು ವಿವರಿಸಿ.", a: "ಪ್ರಜಾಪ್ರಭುತ್ವದಲ್ಲಿ ಜನರಿಂದ ಚುನಾಯಿತರಾದ ಪ್ರತಿನಿಧಿಗಳ ಆಳ್ವಿಕೆ ಇರುತ್ತದೆ, ವಾಕ್ ಮತ್ತು ಅಭಿವ್ಯಕ್ತಿ ಸ್ವಾತಂತ್ರ್ಯವಿರುತ್ತದೆ. ಸರ್ವಾಧಿಕಾರದಲ್ಲಿ ಸಂಪೂರ್ಣ ಅಧಿಕಾರ ಏಕವ್ಯಕ್ತಿ ಅಥವಾ ಸಣ್ಣ ಗುಂಪಿನಲ್ಲಿರುತ್ತದೆ, ಪ್ರಜೆಗಳಿಗೆ ಪ್ರಶ್ನಿಸುವ ಅಥವಾ ವಿರೋಧಿಸುವ ಹಕ್ಕಿರುವುದಿಲ್ಲ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 10: ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು
  // ==========================================
  { id: "U10_F01", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭೂಮಿಯ ನೈಜ ಆಕಾರವನ್ನು ____________ ಎನ್ನಲಾಗಿದೆ.", a: "ಜಿಯಾಯ್ಡ್" },
  { id: "U10_F02", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ನಕ್ಷೆ ತಯಾರಿಸುವ ವಿಜ್ಞಾನ ಮತ್ತು ಕಲೆಗೆ ____________ ಎನ್ನುವರು.", a: "ನಕ್ಷಾಶಾಸ್ತ್ರ" },
  { id: "U10_M01", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ನಕಾಶೆಗಳಲ್ಲಿ ಗಡಿ ರೇಖೆಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಈ ಕೆಳಗಿನ ಯಾವ ಬಣ್ಣದಿಂದ ಗುರುತಿಸುತ್ತಾರೆ?", opts: ["ಕೆಂಪು ಬಣ್ಣ", "ಹಸಿರು ಬಣ್ಣ", "ನೀಲಿ ಬಣ್ಣ", "ಕಪ್ಪು ಬಣ್ಣ"], a: "D) ಕಪ್ಪು ಬಣ್ಣ" },
  { id: "U10_M02", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 2, q: "ವಿಶಾಲವಾದ ಪ್ರದೇಶವನ್ನು ನಿರೂಪಿಸುವ ನಕ್ಷೆಗಳು:", opts: ["ದೊಡ್ಡ ಪ್ರಮಾಣದ ನಕ್ಷೆಗಳು", "ಚಿಕ್ಕ ಪ್ರಮಾಣದ ನಕ್ಷೆಗಳು", "ಸ್ವಾಭಾವಿಕ ನಕ್ಷೆಗಳು", "ಹಂಚಿಕೆ ನಕ್ಷೆಗಳು"], a: "B) ಚಿಕ್ಕ ಪ್ರಮಾಣದ ನಕ್ಷೆಗಳು" },
  { id: "U10_S01", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ನಕ್ಷೆ ಎಂದರೇನು?", a: "ಭೂಮಿಯ ಪೂರ್ಣ ಅಥವಾ ಭಾಗಶಃ ಭಾಗವನ್ನು ಸಮತಲ ಕಾಗದದ ಮೇಲೆ ಮಾನಕಕ್ಕೆ ಅನುಗುಣವಾಗಿ ರೂಪಿಸುವ ಆಕೃತಿಯೇ ನಕ್ಷೆ." },
  { id: "U10_S02", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಅಕ್ಷಾಂಶ ಮತ್ತು ರೇಖಾಂಶಗಳು ನಮಗೆ ಹೇಗೆ ಸಹಾಯ ಮಾಡುತ್ತವೆ?", a: "ನಕ್ಷೆಯ ಮೇಲಿನ ಸ್ಥಳವೊಂದರ ನಿಖರ ಸ್ಥಾನ, ಅಂತರ ಮತ್ತು ದಿಕ್ಕುಗಳನ್ನು ಗುರುತಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ." },
  { id: "U10_S03", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ನಕ್ಷಾ ಸೂಚಿ ಎಂದರೇನು?", a: "ನಕ್ಷೆಯಲ್ಲಿ ವಿವಿಧ ಭೌಗೋಳಿಕ ಅಂಶಗಳನ್ನು ಸೂಚಿಸಲು ಮತ್ತು ಗುರುತಿಸಲು ಬಳಕೆ ಮಾಡುವ ಸಾಂಕೇತಿಕ ಗುರುತುಗಳೇ ನಕ್ಷಾ ಸೂಚಿ." },
  { id: "U10_K01", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ಪಟ್ಟಿ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಉತ್ತಮ ನಕಾಶೆಯು ಹೊಂದಿರಬೇಕಾದ ಅಗತ್ಯ ಮಾಹಿತಿಗಳು ಯಾವುವು?", a: "1) ಶೀರ್ಷಿಕೆ 2) ಮಾನಕ (ಪ್ರಮಾಣ) 3) ಅಕ್ಷಾಂಶ ಮತ್ತು ರೇಖಾಂಶಗಳು 4) ದಿಕ್ಕು 5) ಸೂಚಿ." },
  { id: "U10_K02", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ನಕಾಶೆ ಓದುವ ಕೌಶಲ್ಯ ಬೆಳೆಸಿಕೊಳ್ಳಲು ಯಾವ ನಿರ್ದೇಶನಗಳನ್ನು ಅರಿತಿರಬೇಕು?", a: "ಸ್ಥಳ ಗುರುತಿಸಲು ಅಕ್ಷಾಂಶ-ರೇಖಾಂಶ ತಿಳಿಯುವುದು, ದಿಕ್ಕುಗಳನ್ನು ಗ್ರಹಿಸುವುದು ಮತ್ತು ಅಂತರ ಅಳೆಯಲು ಮಾನಕವನ್ನು ತಿಳಿದಿರಬೇಕು." },
  { id: "U10_L01", unit: "ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳು", type: "ವಿ.ಉ", marks: 4, obj: "ಅಭಿವ್ಯಕ್ತಿ / ಅನ್ವಯ", spec: "ವಿಶ್ಲೇಷಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಭೂಗೋಳಶಾಸ್ತ್ರ ವಿಷಯದ ಕಲಿಕೆಯಲ್ಲಿ ಗ್ಲೋಬ್ ಮತ್ತು ನಕಾಶೆಗಳ ಉಪಯೋಗಗಳನ್ನು ವಿವರಿಸಿ.", a: "ಗ್ಲೋಬ್ ಭೂಮಿಯ ನೈಜ ಗೋಳಾಕಾರ, ಅಕ್ಷದ ವಾಲುವಿಕೆ ಮತ್ತು ದಿನ-ರಾತ್ರಿ ಚಲನೆಗಳನ್ನು ಕಲಿಯಲು ನೆರವಾಗುತ್ತದೆ. ನಕಾಶೆಗಳು ನಗರ, ದೇಶ, ರಸ್ತೆ, ಬೆಳೆಗಳು, ಗಡಿರೇಖೆಗಳನ್ನು ತಿಳಿಯಲು ಮತ್ತು ಸುಲಭವಾಗಿ ಕೊಂಡೊಯ್ಯಲು ಶಿಕ್ಷಕ-ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಅತ್ಯುತ್ತಮ ಬೋಧನಾ ಸಾಧನಗಳಾಗಿವೆ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 11: ಭೂಮಿಯ ಸ್ವರೂಪ
  // ==========================================
  { id: "U11_F01", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಹಿಮಾಲಯ ಪರ್ವತವು ____________ ವಿಧದ ಪರ್ವತಕ್ಕೆ ಉದಾಹರಣೆಯಾಗಿದೆ.", a: "ಮಡಿಕೆ ಪರ್ವತಗಳು" },
  { id: "U11_F02", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಪಂಚದ ಮೇಲ್ಛಾವಣಿ ಎಂದು ಕರೆಯಲ್ಪಡುವ ಪ್ರಸ್ಥಭೂಮಿ ____________.", a: "ಟಿಬೆಟ್ ಪ್ರಸ್ಥಭೂಮಿ" },
  { id: "U11_M01", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ನದಿ ಮತ್ತು ಸರೋವರಗಳ ನಡುವಣ ಸಣ್ಣ ದ್ವೀಪಗಳಿಗೆ ಹೀಗೆಂದು ಕರೆಯುವರು:", opts: ["ದ್ವೀಪ", "ಕಿರುದ್ವೀಪ", "ನಡುಗಡ್ಡೆ", "ದ್ವೀಪಸ್ತೋಮ"], a: "C. ನಡುಗಡ್ಡೆ" },
  { id: "U11_M02", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಹಗಲಿನ ವೇಳೆಯಲ್ಲಿ ಅತಿ ಶಾಖ ಮತ್ತು ರಾತ್ರಿ ವೇಳೆಯಲ್ಲಿ ಶೀತವಾಗಿರುವ ಭೂಭಾಗ:", opts: ["ಪರ್ವತ", "ಮರುಭೂಮಿಗಳು", "ಪ್ರಸ್ಥಭೂಮಿ", "ಮೈದಾನ"], a: "B. ಮರುಭೂಮಿಗಳು" },
  { id: "U11_M03", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ತಿಳುವಳಿಕೆ", spec: "ಆಯ್ಕೆ ಮಾಡುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 2, q: "ಮರುಭೂಮಿಗಳೇ ಇಲ್ಲದ ಖಂಡಗಳು ಯಾವುವು?", opts: ["ಅಂಟಾರ್ಕ್ಟಿಕ ಮತ್ತು ಯುರೋಪ್", "ಏಷ್ಯಾ ಮತ್ತು ಆಸ್ಟ್ರೇಲಿಯಾ", "ಆಫ್ರಿಕಾ ಮತ್ತು ಆಸ್ಟ್ರೇಲಿಯಾ", "ಉತ್ತರ ಮತ್ತು ದಕ್ಷಿಣ ಅಮೆರಿಕ"], a: "A) ಅಂಟಾರ್ಕ್ಟಿಕ ಮತ್ತು ಯುರೋಪ್" },
  { id: "U11_S01", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಪಂಚದ ಅತಿ ಎತ್ತರವಾದ ಶಿಖರ ಯಾವುದು?", a: "ಮೌಂಟ್ ಎವರೆಸ್ಟ್" },
  { id: "U11_S02", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಸ್ಥಭೂಮಿ ಎಂದರೇನು?", a: "ಸಮತಟ್ಟಾದ ಮೇಲ್ಭಾಗ ಮತ್ತು ಕಡಿದಾದ ಬದಿಗಳಿಂದ ಕೂಡಿದ ಎತ್ತರವಾದ ಭೂಭಾಗವೇ ಪ್ರಸ್ಥಭೂಮಿ." },
  { id: "U11_S03", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಓಯಸಿಸ್ ಎಂದರೇನು?", a: "ಮರುಭೂಮಿಯ ಯಾವ ಭಾಗದಲ್ಲಿ ಅಂತರ್ಜಲವು ಚಿಲುಮೆಯ ರೂಪದಲ್ಲಿ ಹೊರಬರುತ್ತದೆಯೋ ಅದನ್ನು ಓಯಸಿಸ್ ಎನ್ನುವರು." },
  { id: "U11_S04", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಪ್ರಪಂಚದ ಅತ್ಯಂತ ವಿಶಾಲವಾದ ಉಷ್ಣ ಮರುಭೂಮಿ ಯಾವುದು?", a: "ಸಹರಾ ಮರುಭೂಮಿ" },
  { id: "U11_S05", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವ.ಉ", marks: 1, obj: "ಜ್ಞಾನ", spec: "ಸ್ಮರಿಸುತ್ತಾನೆ", diff: "ಸುಲಭ", time: 2, q: "ಭಾರತದಲ್ಲಿ ಕಂಡುಬರುವ ಮರುಭೂಮಿ ಯಾವುದು?", a: "ಥಾರ್ ಮರುಭೂಮಿ" },
  { id: "U11_K01", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿಂಗಡಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ನಿರ್ಮಾಣದ ಆಧಾರದ ಮೇಲೆ ಪರ್ವತಗಳ ಮೂರು ವಿಧಗಳನ್ನು ತಿಳಿಸಿ.", a: "1) ಮಡಿಕೆ ಪರ್ವತಗಳು 2) ಖಂಡ ಪರ್ವತಗಳು 3) ಜ್ವಾಲಾಮುಖಿ ಜನಿತ ಪರ್ವತಗಳು." },
  { id: "U11_K02", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ಕಿ.ಉ", marks: 2, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಮೈದಾನ ಎಂದರೇನು? ಮೈದಾನಗಳ ವಿಧಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ವಿಶಾಲವಾದ ಸಮತಟ್ಟಾದ ತಗ್ಗಾದ ಭೂಭಾಗಗಳೇ ಮೈದಾನಗಳು. ವಿಧಗಳು: ರಚನಾ ಮೈದಾನ, ಸವೆತದ ಮೈದಾನ ಮತ್ತು ಸಂಚಯನ ಮೈದಾನ." },
  { id: "U11_K03", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ಕಿ.ಉ", marks: 2, obj: "ಜ್ಞಾನ", spec: "ಹೆಸರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 5, q: "ಭಾರತಕ್ಕೆ ಸೇರಿದ ಎರಡು ಪ್ರಮುಖ ದ್ವೀಪ ಸಮೂಹಗಳನ್ನು ಹೆಸರಿಸಿ.", a: "ಅಂಡಮಾನ್ ಮತ್ತು ನಿಕೋಬಾರ್ ದ್ವೀಪಗಳು ಹಾಗೂ ಲಕ್ಷದ್ವೀಪಗಳು." },
  { id: "U11_L01", unit: "ಭೂಮಿಯ ಸ್ವರೂಪ", type: "ವಿ.ಉ", marks: 4, obj: "ತಿಳುವಳಿಕೆ", spec: "ವಿವರಿಸುತ್ತಾನೆ", diff: "ಸಾಧಾರಣ", time: 8, q: "ಪರ್ವತಗಳ ನಾಲ್ಕು ಪ್ರಮುಖ ಪ್ರಾಮುಖ್ಯತೆಗಳನ್ನು ಬರೆಯಿರಿ.", a: "ಪರ್ವತಗಳು ದೇಶಗಳ ನಡುವೆ ಸ್ವಾಭಾವಿಕ ಗಡಿಗಳನ್ನು ನಿರ್ಮಿಸುತ್ತವೆ; ನೈಸರ್ಗಿಕ ಸಂಪನ್ಮೂಲಗಳ ಉಗ್ರಾಣಗಳಾಗಿವೆ; ನದಿಗಳ ಉಗಮ ಸ್ಥಾನಗಳಾಗಿದ್ದು ಜಲವಿದ್ಯುತ್ ಉತ್ಪಾದನೆಗೆ ನೀರೊದಗಿಸುತ್ತವೆ ಹಾಗೂ ವಾಯುಗುಣದ ಮೇಲೆ ಹಿತಕರ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ." },

  // ==========================================
  // ಅಧ್ಯಾಯ 12: ಭಾರತದ ನಕ್ಷೆ (ಕೌಶಲ)
  // ==========================================
  { id: "U12_M01", unit: "ಭಾರತದ ನಕ್ಷೆ", type: "ವಿ.ಉ", marks: 4, obj: "ಪ್ರಶಂಸೆ / ಕೌಶಲ", spec: "ರಚಿಸಿ ಗುರುತಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಭಾರತದ ನಕ್ಷೆಯನ್ನು ಬಿಡಿಸಿ ಕೆಳಗಿನ ಸ್ಥಳಗಳನ್ನು ಗುರುತಿಸಿ: ಅ) ಬಿಹಾರ ಆ) ವಡೋದರ ಇ) ಚೆನ್ನೈ ಈ) ದೆಹಲಿ", a: "ಭಾರತದ ನಕ್ಷೆ ಹೊರರೇಖೆಗೆ 1 ಅಂಕ; ಸ್ಥಳಗಳ ನಿಖರ ಗುರುತಿಸುವಿಕೆಗೆ ತಲಾ 1 ಅಂಕ (ದೆಹಲಿ, ಬಿಹಾರ, ವಡೋದರ, ಚೆನ್ನೈ)." },
  { id: "U12_M02", unit: "ಭಾರತದ ನಕ್ಷೆ", type: "ವಿ.ಉ", marks: 4, obj: "ಪ್ರಶಂಸೆ / ಕೌಶಲ", spec: "ರಚಿಸಿ ಗುರುತಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಭಾರತದ ನಕ್ಷೆ ಬಿಡಿಸಿ ಕೆಳಗಿನ ಐತಿಹಾಸಿಕ ಸ್ಥಳಗಳನ್ನು ಗುರುತಿಸಿ: ಅ) ತಲಕಾಡು ಆ) ಬನವಾಸಿ ಇ) ಬಾದಾಮಿ ಈ) ಕಂಚಿ", a: "ನಕ್ಷೆ ಹೊರರೇಖೆಗೆ 1 ಅಂಕ; ತಲಕಾಡು, ಬನವಾಸಿ, ಬಾದಾಮಿ, ಕಂಚಿ ಸ್ಥಳಗಳಿಗೆ ತಲಾ 1 ಅಂಕ." },
  { id: "U12_M03", unit: "ಭಾರತದ ನಕ್ಷೆ", type: "ವಿ.ಉ", marks: 4, obj: "ಪ್ರಶಂಸೆ / ಕೌಶಲ", spec: "ರಚಿಸಿ ಗುರುತಿಸುತ್ತಾನೆ", diff: "ಕಠಿಣ", time: 8, q: "ಭಾರತದ ನಕಾಶೆಯಲ್ಲಿ ಕೆಳಗಿನ ಧಾರ್ಮಿಕ ಕೇಂದ್ರಗಳನ್ನು ಗುರುತಿಸಿ: ಅ) ಶ್ರವಣಬೆಳಗೊಳ ಆ) ಸಾರನಾಥ ಇ) ಕಲ್ಕತ್ತ ಈ) ಮುಂಬೈ", a: "ಹೊರರೇಖೆಗೆ 1 ಅಂಕ; ಶ್ರವಣಬೆಳಗೊಳ, ಸಾರನಾಥ, ಕಲ್ಕತ್ತ, ಮುಂಬೈ ಸ್ಥಳ ಗುರುತಿಸುವಿಕೆಗೆ ತಲಾ 1 ಅಂಕ." }
